<?php

namespace App\Domain\Integration\Webhooks;

use App\Domain\Integration\Models\IntegrationConnector;
use App\Domain\Integration\Models\WebhookDelivery;
use App\Domain\Integration\Models\WebhookSubscription;
use App\Domain\Platform\Services\AuditLogger;
use App\Models\User;
use App\Support\Exceptions\BusinessRuleViolation;
use App\Support\Tenancy\TenantContext;
use Illuminate\Support\Str;

/**
 * Webhook subscriptions of the current organization. The signing secret is
 * generated by the platform, returned once and stored encrypted.
 */
class WebhookService
{
    public function __construct(
        private readonly TenantContext $tenant,
        private readonly OutboxRecorder $outbox,
        private readonly AuditLogger $audit,
    ) {}

    /** @return array{0: WebhookSubscription, 1: string} the subscription and its secret (shown once) */
    public function create(array $data, User $actor): array
    {
        UrlGuard::assertAcceptable($data['url']);
        $this->assertEventTypes($data['event_types']);
        if (WebhookSubscription::query()->where('status', '!=', 'disabled')->count() >= config('integrations.webhooks.max_subscriptions')) {
            throw new BusinessRuleViolation('webhook_limit_reached', 'The organization has the maximum number of webhook subscriptions. Disable one first.', 409);
        }
        if (isset($data['connector_id'])) {
            IntegrationConnector::query()->findOrFail($data['connector_id']);
        }

        $secret = Str::random(48);
        $subscription = WebhookSubscription::query()->create($data + ['secret' => $secret, 'status' => 'active', 'created_by' => $actor->id]);
        $this->audit->record('integration.webhook.created', $subscription, new: array_intersect_key($data, array_flip(['name', 'url', 'event_types', 'connector_id'])));

        return [$subscription, $secret];
    }

    public function update(WebhookSubscription $subscription, array $data): WebhookSubscription
    {
        if (isset($data['url'])) {
            UrlGuard::assertAcceptable($data['url']);
        }
        if (isset($data['event_types'])) {
            $this->assertEventTypes($data['event_types']);
        }
        $original = $subscription->getAttributes();
        $subscription->fill($data)->save();
        [$old, $new] = $this->audit->diff($subscription, $original);
        if ($new !== []) {
            $this->audit->record('integration.webhook.updated', $subscription, $old, $new);
        }

        return $subscription;
    }

    public function setStatus(WebhookSubscription $subscription, string $status): WebhookSubscription
    {
        $before = $subscription->status;
        $subscription->forceFill(['status' => $status, 'status_reason' => null] + ($status === 'active' ? ['consecutive_failures' => 0] : []))->save();
        $this->audit->record('integration.webhook.status_changed', $subscription, ['status' => $before], ['status' => $status]);

        if ($status === 'active') {
            // Resume: send what queued up while paused.
            WebhookDelivery::query()->where('subscription_id', $subscription->id)->where('status', 'pending')->pluck('id')
                ->each(fn ($id) => DeliverWebhook::dispatch($id));
        }

        return $subscription;
    }

    public function rotateSecret(WebhookSubscription $subscription): string
    {
        $secret = Str::random(48);
        $subscription->forceFill(['secret' => $secret])->save();
        $this->audit->record('integration.webhook.secret_rotated', $subscription);

        return $secret;
    }

    /** Queues a webhook.test event for this subscription only. */
    public function test(WebhookSubscription $subscription): int
    {
        if ($subscription->status !== 'active') {
            throw new BusinessRuleViolation('webhook_not_active', 'Activate the subscription before testing it.', 409);
        }

        return $this->outbox->write($this->tenant->id(), 'webhook.test', 'webhook_subscription', $subscription->id,
            ['message' => 'Test event from the integration gateway.', 'subscription' => $subscription->name], now()->toIso8601String(), null, [$subscription])[0];
    }

    /** A dead or failed delivery is sent again (attempts start over). */
    public function redeliver(WebhookDelivery $delivery): WebhookDelivery
    {
        if (! in_array($delivery->status, ['dead', 'failed'], true)) {
            throw new BusinessRuleViolation('webhook_delivery_not_redeliverable', "A {$delivery->status} delivery cannot be redelivered.", 409);
        }
        $delivery->forceFill(['status' => 'pending', 'attempts' => 0, 'next_attempt_at' => null])->save();
        $this->audit->record('integration.webhook.redelivered', $delivery);
        DeliverWebhook::dispatch($delivery->id);

        return $delivery;
    }

    private function assertEventTypes(array $types): void
    {
        $unknown = array_diff($types, [...OutboundEvents::types(), '*']);
        if ($unknown !== []) {
            throw new BusinessRuleViolation('webhook_event_type_unknown', 'Unknown event types: '.implode(', ', $unknown).'.', 422, ['event_types' => OutboundEvents::types()]);
        }
    }
}
